CREATE TABLE life_support_audit (
    log_entry_number SERIAL PRIMARY KEY,
    patient_id TEXT NOT NULL,
    status_before TEXT,
    status_after TEXT,
    changed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE OR REPLACE FUNCTION log_life_support_change()
RETURNS TRIGGER AS $$
BEGIN
    IF OLD.life_support IS DISTINCT FROM NEW.life_support THEN
        INSERT INTO life_support_audit (patient_id, status_before, status_after)
        VALUES (NEW.immu_recip_registry, OLD.life_support, NEW.life_support);
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_life_support_change
AFTER UPDATE ON recipients_immunology
FOR EACH ROW
WHEN (OLD.life_support IS DISTINCT FROM NEW.life_support)
EXECUTE FUNCTION log_life_support_change();

